#!/usr/bin/env python3
"""Offline EPIC collective collector: JSON stdin/stdout entry point.

Reads one UTF-8 JSON batch request on stdin, validates the whole batch first
and writes exactly one JSON object on stdout: either the per-case
certificates or {"error":"invalid"} for an illegal request.
"""
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

MAX_INPUT = 4 * 1024 * 1024


def _load_request(raw):
    """Validate the whole batch before any replay work happens."""
    from request import load
    return load(raw)


def _run_case(case):
    from collector import Case, PRIM_INDEX
    run = Case(PRIM_INDEX[case['primitive']], case['mode'], case['root'],
               case['segments'], case['words'], case['capacity'],
               case['start'], case.get('trace', 0))
    run.replay(case['events'])
    return run.certificate()


def solve(request):
    cases = request['cases']
    if not cases:
        return {'cases': []}
    return {'cases': [_run_case(case) for case in cases]}


def main():
    try:
        raw = sys.stdin.buffer.read(MAX_INPUT + 1)
    except Exception:
        sys.stdout.write('{"error":"invalid"}\n')
        return 0
    try:
        request = _load_request(raw)
    except Exception:
        sys.stdout.write('{"error":"invalid"}\n')
        sys.stdout.flush()
        return 0
    response = solve(request)
    sys.stdout.write(json.dumps(response, separators=(',', ':'),
                                allow_nan=False))
    sys.stdout.write('\n')
    sys.stdout.flush()
    return 0


if __name__ == '__main__':
    sys.exit(main())
