/* FNV-1a/64 folding accelerator for the offline collector certificates.
 *
 * The Python collector owns every protocol decision; this translation unit
 * only provides a byte-exact fold of the certificate byte sequence so that
 * large retained windows stay cheap.  It is optional: the Python fallback
 * produces identical results.
 */
#include <stdint.h>
#include <stddef.h>

#define FNV_PRIME UINT64_C(1099511628211)

uint64_t epic_fnv1a(uint64_t h, const uint8_t *buf, size_t len)
{
    const uint8_t *end = buf + len;
    while (buf + 16 <= end) {
        h ^= (uint64_t)buf[0];
        h *= FNV_PRIME;
        h ^= (uint64_t)buf[1];
        h *= FNV_PRIME;
        h ^= (uint64_t)buf[2];
        h *= FNV_PRIME;
        h ^= (uint64_t)buf[3];
        h *= FNV_PRIME;
        h ^= (uint64_t)buf[4];
        h *= FNV_PRIME;
        h ^= (uint64_t)buf[5];
        h *= FNV_PRIME;
        h ^= (uint64_t)buf[6];
        h *= FNV_PRIME;
        h ^= (uint64_t)buf[7];
        h *= FNV_PRIME;
        h ^= (uint64_t)buf[8];
        h *= FNV_PRIME;
        h ^= (uint64_t)buf[9];
        h *= FNV_PRIME;
        h ^= (uint64_t)buf[10];
        h *= FNV_PRIME;
        h ^= (uint64_t)buf[11];
        h *= FNV_PRIME;
        h ^= (uint64_t)buf[12];
        h *= FNV_PRIME;
        h ^= (uint64_t)buf[13];
        h *= FNV_PRIME;
        h ^= (uint64_t)buf[14];
        h *= FNV_PRIME;
        h ^= (uint64_t)buf[15];
        h *= FNV_PRIME;
        buf += 16;
    }
    while (buf < end) {
        h ^= (uint64_t)*buf++;
        h *= FNV_PRIME;
    }
    return h;
}
