import json, random, sys
sys.path.insert(0, 'project'); sys.path.insert(0, 'dev')
from collector import Case, PRIM_INDEX, BCAST, BARRIER, GATHER, SCATTER, REDUCE, ALLREDUCE
from fuzz import gen_case
from fuzz2 import gen as gen2

QMAX = {}


def invariants(case, cert):
    st = cert['state']
    prim = case['primitive']
    K = case['segments']
    N = case['capacity']
    root = case['root']
    errs = []
    b, occ = st[0], st[1]
    R, S, A, U = st[2:6], st[6:10], st[10:14], st[14:18]
    if st[22] + st[23] + st[24] + st[25] != st[18]:
        errs.append('data classification total')
    if st[30] or st[31]:
        errs.append('reserved counters nonzero')
    if any(v < 0 for v in st):
        errs.append('negative state')
    if occ > N:
        errs.append('occupied exceeds capacity')
    if any(v > K for v in R):
        errs.append('R exceeds K')
    for r in range(4):
        if U[r] > R[r]:
            errs.append('U exceeds R')
    for d in range(4):
        if A[d] > S[d]:
            errs.append('A exceeds S')
        limit = (3 * K if prim == 'allgather' else
                 0 if (prim == 'reduce' and d != root) or (prim == 'broadcast' and d == root)
                 else 1 if prim == 'barrier' else
                 K // 4 if prim == 'reducescatter' else K)
        if S[d] > limit or A[d] > limit:
            errs.append('S/A exceeds output space (d=%d)' % d)
    if cert['bytes'] != cert['packets'] * 0 and False:
        pass
    # bytes must equal the sum of frame lengths implied by txdata/txack
    D = case['words']
    expect = st[20] * (58 + 4 * D) + st[21] * 62
    if prim == 'barrier':
        expect = st[20] * 58 + st[21] * 62
    if cert['bytes'] != expect:
        errs.append('bytes %d != %d' % (cert['bytes'], expect))
    if cert['packets'] != st[20] + st[21]:
        errs.append('packets != tx counters')
    if cert['trace'] is None or len(cert['trace']) > case.get('trace', 0):
        errs.append('trace length')
    for s in cert['snapshots']:
        if set(s) != {'tag', 'state', 'buffer', 'wire_sha256', 'packets', 'bytes'}:
            errs.append('snapshot keys %r' % sorted(s))
    if set(cert) != {'state', 'buffer', 'wire_sha256', 'packets', 'bytes',
                     'snapshots', 'trace'}:
        errs.append('certificate keys %r' % sorted(cert))
    if len(cert['buffer']) != 16 or cert['buffer'].lower() != cert['buffer']:
        errs.append('buffer digest format')
    return errs


def run(seed, iters):
    rng = random.Random(seed)
    bad = 0
    for i in range(iters):
        case = gen_case(rng) if i % 2 else gen2(rng)
        try:
            c = Case(PRIM_INDEX[case['primitive']], case['mode'], case['root'],
                     case['segments'], case['words'], case['capacity'],
                     case['start'], case.get('trace', 0))
            c.replay(case['events'])
            cert = c.certificate()
            errs = invariants(case, cert)
            # re-run to confirm determinism
            c2 = Case(PRIM_INDEX[case['primitive']], case['mode'], case['root'],
                      case['segments'], case['words'], case['capacity'],
                      case['start'], case.get('trace', 0))
            c2.replay(case['events'])
            if c2.certificate() != cert:
                errs.append('nondeterministic')
        except Exception as exc:
            import traceback
            traceback.print_exc()
            errs = ['exception']
        if errs:
            bad += 1
            print('CASE', json.dumps(case))
            for e in errs:
                print('   ', e)
            if bad > 3:
                break
    print('iterations', iters, 'failures', bad)
    return 1 if bad else 0


if __name__ == '__main__':
    sys.exit(run(int(sys.argv[1]) if len(sys.argv) > 1 else 1,
                 int(sys.argv[2]) if len(sys.argv) > 2 else 200))
