def _result_payload(self, d, q):
    prim = self.prim
    if prim == ALLREDUCE:
        if q >= self.K:
            return None
        p = q
    elif prim == REDUCE:
        if d != self.root or q >= self.K:
            return None
        p = q
    elif prim == BCAST:
        if d == self.root or q >= self.K:
            return None
        p = q
    elif prim == BARRIER:
        if q >= 1:
            return None
        p = 0
    elif prim == GATHER:
        if q >= self.qmax[d]:
            return None
        p = q // 3
    else:
        if q >= self.block:
            return None
        p = d * self.block + q
    slot = self.slots.get(p)
    if slot is None or not slot[1]:
        return None
    if prim == GATHER:
        return slot[2][self.rank_of[d][q % 3]]
    return slot[3]

# ------------------------------------------------------------------
# retirement
# ------------------------------------------------------------------
def _retire(self):
    slots = self.slots
    b = self.b
    K = self.K
    prim = self.prim
    A = self.A
    U = self.U
    root = self.root
    block = self.block
    while b < K:
        slot = slots.get(b)
        if slot is None or not slot[1]:
            break
        p = b
        if prim == ALLREDUCE or prim == BCAST:
            ok = True
            for d in range(4):
                if prim == BCAST and d == root:
                    continue
                if A[d] <= p:
                    ok = False
                    break
            if not ok:
                break
        elif prim == REDUCE:
            if A[root] <= p:
                break
        elif prim == BARRIER:
            if not (A[0] >= 1 and A[1] >= 1 and A[2] >= 1 and A[3] >= 1):
