        ok = True
        for r in self.req_list:
            if U[r] <= p:
                ok = False
                break
        if not ok:
            break
        del slots[b]
        b += 1
    self.b = b

# ------------------------------------------------------------------
# event replay
# ------------------------------------------------------------------
def replay(self, events):
    for op in events:
        name = op['op']
        if name == 'data':
            self._ev_data(op)
        elif name == 'train':
            self._ev_train(op)
        elif name == 'ack':
            self._ack_packet(op['rank'], op['upto'] & MASK24)
